{-# LANGUAGE DataKinds         #-}
{-# LANGUAGE DeriveGeneric     #-}
{-# LANGUAGE DeriveTraversable #-}
{-# LANGUAGE FlexibleContexts  #-}
{-# LANGUAGE FlexibleInstances #-}
{-# LANGUAGE GADTs             #-}
{-# LANGUAGE KindSignatures    #-}
{-# LANGUAGE LambdaCase        #-}
{-# LANGUAGE PatternSynonyms   #-}
{-# LANGUAGE RankNTypes        #-}
{-# LANGUAGE TemplateHaskell   #-}
{-# LANGUAGE TypeFamilies      #-}
{-# OPTIONS_GHC -Wno-missing-signatures -Wno-redundant-constraints -Wno-orphans #-}
-- | Scope-safe dependent pairs syntax, generated by free-foil's Template
-- Haskell from "DependentPairs.Raw": the signature @TermSig@, the term type
-- @FFTerm@, the pattern type @FFPattern@ of one name or two, a pattern
-- synonym per constructor, and the conversions @toTerm@ and @fromTerm@.
module DependentPairs.Generated where

import qualified Control.Monad.Foil as Foil
import Control.Monad.Free.Foil (AST)
import Control.Monad.Free.Foil.TH.MkFreeFoil
import Generics.Kind.TH (deriveGenericK)

import DependentPairs.Raw
import DependentPairs.Syntax.Print (printTree)

mkFreeFoil config

deriveGenericK ''FFPattern
instance Foil.SinkableK FFPattern
instance Foil.HasNameBinders FFPattern
instance Foil.UnifiablePattern FFPattern

mkFreeFoilConversions config

-- | Terms print through the raw conversion and BNFC's printer. Variables are
-- named by foil identifier, so the output re-parses but is not α-canonical.
instance Show (AST FFPattern TermSig n) where
  show = printTree . fromTerm
